  overlap = temporalChoice(overlap, ["reject", "earlier", "later"] as const, "temporal local arithmetic.overlap");
  gap = temporalChoice(gap, ["reject", "shift_forward", "shift_backward"] as const, "temporal local arithmetic.gap");
